from __future__ import annotations
import base64,gzip,subprocess,sys

def main()->int:
    subprocess.check_call(["uv","pip","install","--python",sys.executable,"yfinance","pandas","numpy"])
    payload=""
    code=gzip.decompress(base64.b64decode(payload))
    ns={"__name__":"__main__"}
    exec(compile(code,"chem_full_yf.py","exec"),ns,ns)
    return 0

if __name__=="__main__":
    raise SystemExit(main())
